{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Entecavir, a carbocyclic guanine nucleoside analog closely related to the query, has 100% absolute oral bioavailability in humans, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Cladribine, a polar purine nucleoside, has absolute oral bioavailability of 48% ± 8% in patients, showing that similar nucleoside polarity still permits F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Fludarabine, a fluorinated purine nucleoside, has systemic availability of approximately 55% after oral tablets in patients, supporting high oral bioavailability for related nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Clofarabine, another halogenated purine nucleoside, has oral bioavailability of 57.5% in patients, reinforcing that nucleoside analogs with high polarity can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Didanosine, a less similar acid-labile dideoxynucleoside, showed only 13% oral bioavailability in children; this contradictory example has low transferability to the carbocyclic guanine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a carbocyclic guanine nucleoside analog. The closest analogue, entecavir, has 100% oral bioavailability in humans, and multiple related purine nucleosides (cladribine, fludarabine, clofarabine) show F values around 40-60%, all above the 20% threshold. The only low-F evidence comes from didanosine, which is structurally less similar and has acid-lability issues not shared by the query. Therefore high oral bioavailability is predicted.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the exact query molecule.",
    "Transporter and metabolic stability data for the query are not available.",
    "The effect of the two hydroxymethyl groups on absorption relative to entecavir is not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

